+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final MessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>();
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message);
+
+        send.addClickListener(e -> send());
+        send.addClickShortcut(Key.ENTER);
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+
+        registerEnableOnEdit(name);
+        registerEnableOnEdit(email);
+        registerEnableOnEdit(phone);
+        registerEnableOnEdit(message);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+
+        add(form, send, grid);
+
+        refreshGrid();
+    }
+
+    private void registerEnableOnEdit(HasValue<?, ?> field) {
+        field.addValueChangeListener(e -> {
+            if (e.isFromClient()) {
+                send.setEnabled(true);
+            }
+        });
+    }
+
+    private void send() {
+        if (!validate()) {
+            return;
+        }
+
+        ContactMessage contactMessage = new ContactMessage(name.getValue().trim(), email.getValue().trim(),
+                phone.getValue().trim(), message.getValue().trim(), Instant.now());
+        messageService.add(contactMessage);
+        refreshGrid();
+        clearForm();
+
+        Notification.show("Message sent");
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        if (nameValue.isEmpty()) {
+            name.setInvalid(true);
+            name.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            email.setInvalid(true);
+            email.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            email.setInvalid(true);
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (messageValue.isEmpty()) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void clearForm() {
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.getMessages());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Leave without sending?");
+        dialog.add("You have unsaved changes. If you leave now, they will be lost.");
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
